"use client";

import { useEffect, useRef, useState } from "react";
import { FileCheck2, FolderOpen, RefreshCw } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { integrationErrorMessage } from "@/hooks/use-integration-operation";
import { Alert } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  IntegrationError,
  type IntegrationConnection,
  type IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  parseDrivePickedFiles,
  type DrivePickedFile,
  type DrivePickerBinding,
} from "@/lib/integrations/drive-picker";
import { withIntegrationCancellation } from "@/lib/integrations/cancelled-task";
import {
  acceptIntegrationConnectionResponse,
  integrationConnectionSnapshotMatches,
} from "@/lib/integrations/connection-snapshot";
import { ProductEmpty, ProductPanel } from "./product-ui";

export function DrivePickerPanel({
  binding,
  canManage = true,
  onConnectionChange,
  ...props
}: IntegrationWorkbenchProps & {
  binding?: DrivePickerBinding;
  /** Presentation restriction; the registration backend enforces authorization. */
  canManage?: boolean;
  onConnectionChange(connection: IntegrationConnection): void;
}) {
  const { l, locale } = useLanguage();
  const [files, setFiles] = useState<DrivePickedFile[]>([]);
  const [confirmed, setConfirmed] = useState(false);
  const [selectionConnection, setSelectionConnection] =
    useState<IntegrationConnection | null>(null);
  const [busy, setBusy] = useState<"picker" | "register" | "refresh" | null>(
    null,
  );
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const request = useRef<AbortController | null>(null);
  const currentConnection = useRef(props.connection);
  const retryKey = useRef<string | null>(null);
  const ready =
    props.connection.status === "connected" &&
    props.connection.grantedPermissions.includes("files.read");
  useEffect(() => {
    currentConnection.current = props.connection;
  }, [props.connection]);
  useEffect(() => {
    request.current?.abort();
    request.current = null;
    setFiles([]);
    setConfirmed(false);
    setSelectionConnection(null);
    setBusy(null);
    setError(null);
    setNotice(null);
    retryKey.current = null;
    return () => request.current?.abort();
  }, [
    binding,
    props.adapter,
    props.scope.workspaceId,
    props.connection.id,
    props.connection.providerOptionId,
  ]);
  useEffect(() => {
    if (!ready || !canManage) {
      request.current?.abort();
      request.current = null;
      setFiles([]);
      setConfirmed(false);
      setSelectionConnection(null);
      setBusy(null);
      retryKey.current = null;
    }
  }, [ready, canManage]);
  async function run(kind: "picker" | "register" | "refresh") {
    if (request.current || !ready) return;
    if (kind === "register" && !canManage) {
      setError(integrationErrorMessage("permission-denied", locale));
      return;
    }
    const controller = new AbortController();
    const scope = {
      workspaceId: props.scope.workspaceId,
      signal: controller.signal,
    };
    const abort = () => controller.abort();
    props.scope.signal?.addEventListener("abort", abort, { once: true });
    if (props.scope.signal?.aborted) controller.abort();
    request.current = controller;
    setBusy(kind);
    setError(null);
    setNotice(null);
    try {
      if (kind === "picker") {
        let selected: DrivePickedFile[];
        if (props.adapter.mode === "demo") {
          const resources = await props.adapter.resources(
            props.definition.id,
            scope,
          );
          selected = resources.slice(0, 3).map((resource) => ({
            id: resource.id,
            name: resource.name,
            mimeType: "application/vnd.google-apps.document",
          }));
        } else {
          if (!binding) throw new IntegrationError("configuration-required");
          const selection = await withIntegrationCancellation(
            () => binding.select({ connection: props.connection, scope }),
            scope,
          );
          if (controller.signal.aborted) return;
          if (selection.kind === "cancelled") {
            setNotice(
              l(
                "File selection cancelled. Your authorized files are unchanged.",
                "Selección cancelada. Tus archivos autorizados siguen igual.",
              ),
            );
            return;
          }
          selected = parseDrivePickedFiles(selection.files);
        }
        if (!controller.signal.aborted) {
          setFiles(selected);
          setConfirmed(false);
          setSelectionConnection(structuredClone(props.connection));
          retryKey.current = null;
        }
      } else if (kind === "register") {
        if (!confirmed || !files.length)
          throw new IntegrationError("validation");
        if (
          !selectionConnection ||
          !integrationConnectionSnapshotMatches(
            selectionConnection,
            props.connection,
          )
        ) {
          setConfirmed(false);
          throw new IntegrationError("conflict");
        }
        retryKey.current ??= crypto.randomUUID();
        const result =
          props.adapter.mode === "demo"
            ? await props.adapter.configure(
                props.connection.id,
                {
                  configuration: selectionConnection.configuration,
                  permissions: selectionConnection.grantedPermissions,
                  resourceIds: [
                    ...new Set([
                      ...selectionConnection.resourceIds,
                      ...files.map((file) => file.id),
                    ]),
                  ],
                  revision: selectionConnection.revision,
                },
                scope,
              )
            : await withIntegrationCancellation(
                () =>
                  binding!.register({
                    connection: selectionConnection,
                    files: structuredClone(files),
                    idempotencyKey: retryKey.current!,
                    scope,
                  }),
                scope,
              );
        const connection = acceptIntegrationConnectionResponse(
          result,
          currentConnection.current,
          props.definition,
          scope,
        );
        if (
          !integrationConnectionSnapshotMatches(
            selectionConnection,
            currentConnection.current,
          )
        ) {
          setConfirmed(false);
          throw new IntegrationError("conflict");
        }
        // Only the authoritative backend response establishes the new file scope.
        if (controller.signal.aborted) return;
        onConnectionChange(connection);
        setFiles([]);
        setConfirmed(false);
        setSelectionConnection(null);
        retryKey.current = null;
        setNotice(
          l(
            "Selected files reconciled with the connection. Reopen the resource selector to inspect their current status.",
            "Archivos elegidos conciliados con la conexión. Vuelve a abrir el selector de recursos para revisar su estado.",
          ),
        );
        try {
          await props.adapter.resources(props.definition.id, scope);
        } catch {
          if (!controller.signal.aborted)
            setNotice(
              l(
                "File registration confirmed. The resource list could not refresh; use Refresh authorized files to try again.",
                "Registro de archivos confirmado. No se pudo actualizar la lista; usa Actualizar archivos autorizados para reintentar.",
              ),
            );
        }
      } else {
        const result = await props.adapter.get(props.definition.id, scope);
        await props.adapter.resources(props.definition.id, scope);
        if (!controller.signal.aborted) {
          onConnectionChange(
            acceptIntegrationConnectionResponse(
              result,
              currentConnection.current,
              props.definition,
              scope,
            ),
          );
          setNotice(
            l(
              "Authorized file scope refreshed.",
              "Alcance de archivos autorizados actualizado.",
            ),
          );
        }
      }
    } catch (cause) {
      if (!controller.signal.aborted)
        setError(
          integrationErrorMessage(
            cause instanceof IntegrationError ? cause.code : "provider-error",
            locale,
          ),
        );
    } finally {
      props.scope.signal?.removeEventListener("abort", abort);
      if (request.current === controller) {
        request.current = null;
        setBusy(null);
      }
    }
  }
  return (
    <ProductPanel
      title={l("Choose files from Drive", "Elegir archivos de Drive")}
      description={l(
        "Select specific files, review them, then let your backend reconcile their authorized scope.",
        "Elige archivos concretos, revísalos y permite que tu backend concilie su alcance autorizado.",
      )}
    >
      {props.adapter.mode === "consumer" && !binding && (
        <ProductEmpty>
          {l(
            "Provide a Drive Picker binding to enable your Google file dialog. The native helper and limited-file OAuth recipe are included in the source.",
            "Aporta un binding de Drive Picker para activar tu diálogo Google. El helper nativo y la receta OAuth de archivos limitados están en el código.",
          )}
        </ProductEmpty>
      )}
      {props.adapter.mode === "demo" && (
        <p className="mb-4 text-xs leading-6 text-muted-foreground">
          {l(
            "This preview selects three local sample files. Google is loaded only by the opt-in consumer binding.",
            "Esta vista elige tres archivos locales de ejemplo. Google se carga solo con el binding optativo del consumidor.",
          )}
        </p>
      )}
      {!canManage && (
        <p className="mb-4 text-xs leading-6 text-muted-foreground">
          {l(
            "Your current role cannot register new files with this connection.",
            "Tu rol actual no puede registrar nuevos archivos en esta conexión.",
          )}
        </p>
      )}
      <div className="mt-4 flex flex-wrap gap-2">
        <Button
          variant="outline"
          disabled={
            !ready || !!busy || (props.adapter.mode === "consumer" && !binding)
          }
          loading={busy === "picker"}
          onClick={() => void run("picker")}
        >
          <FolderOpen aria-hidden />
          {l("Open file picker", "Abrir selector de archivos")}
        </Button>
        <Button
          variant="ghost"
          disabled={!ready || !!busy}
          loading={busy === "refresh"}
          onClick={() => void run("refresh")}
        >
          <RefreshCw aria-hidden />
          {l("Refresh authorized files", "Actualizar archivos autorizados")}
        </Button>
        {busy && (
          <Button variant="ghost" onClick={() => request.current?.abort()}>
            {l("Cancel", "Cancelar")}
          </Button>
        )}
      </div>
      {!!files.length && (
        <div className="mt-5 space-y-4 rounded-xl border border-primary/20 bg-primary/5 p-4">
          <ul className="grid gap-3">
            {files.map((file) => (
              <li
                key={file.id}
                className="flex min-w-0 items-start gap-3 text-xs"
              >
                <FileCheck2
                  aria-hidden
                  className="size-4 shrink-0 text-primary"
                />
                <div className="min-w-0">
                  <p className="font-medium wrap-break-word">{file.name}</p>
                  <p className="mt-1 wrap-break-word text-muted-foreground">
                    {file.mimeType}
                  </p>
                </div>
              </li>
            ))}
          </ul>
          <label className="flex min-h-11 items-start gap-3 text-xs leading-6">
            <Checkbox
              checked={confirmed}
              onCheckedChange={(value) => setConfirmed(value === true)}
              disabled={!!busy || !canManage}
            />
            {l(
              "Register only these selected files with this workspace.",
              "Registrar solo estos archivos elegidos en este espacio.",
            )}
          </label>
          <Button
            loading={busy === "register"}
            disabled={!confirmed || !!busy || !ready || !canManage}
            onClick={() => void run("register")}
          >
            {l("Confirm selected files", "Confirmar archivos elegidos")}
          </Button>
        </div>
      )}
      {error && <Alert className="mt-4" variant="destructive" title={error} />}
      {notice && <Alert className="mt-4" variant="success" title={notice} />}
    </ProductPanel>
  );
}

import type {
  IntegrationAction,
  IntegrationDefinition,
  IntegrationField,
  IntegrationOperationKind,
  IntegrationRecord,
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export function findProductAction(
  definition: IntegrationDefinition,
  ...kinds: IntegrationOperationKind[]
) {
  for (const kind of kinds) {
    const action = definition.actions.find((item) => item.kind === kind);
    if (action) return action;
  }
  return undefined;
}

/** A configuration or permission change discards drafts tied to the old scope. */
export function productScopeKey({
  definition,
  connection,
  scope,
  adapter,
}: IntegrationWorkbenchProps) {
  return JSON.stringify([
    adapter.mode,
    definition.id,
    connection.id,
    connection.providerOptionId,
    connection.workspaceId,
    scope.workspaceId,
    connection.revision,
    connection.status,
    [...connection.resourceIds].sort(),
    [...connection.grantedPermissions].sort(),
  ]);
}

export function defaultActionValues(
  action?: IntegrationAction,
): IntegrationValues {
  return Object.fromEntries(
    (action?.fields ?? []).map((field) => [
      field.id,
      field.type === "toggle"
        ? false
        : field.type === "select"
          ? (field.options?.[0]?.value ?? "")
          : "",
    ]),
  );
}

/** A create recipe must never reuse the selected source record as its target. */
export function productRecordNeedsTarget(action?: IntegrationAction) {
  return (
    action?.kind === "update-record" ||
    (action?.kind === "save-record" &&
      action.fields.some(
        (field) => ["recordId", "id"].includes(field.id) && field.required,
      ))
  );
}

/** Demo reads can start immediately; consumer references remain explicit inputs. */
export function productReadDefaults(
  action: IntegrationAction | undefined,
  props: IntegrationWorkbenchProps,
): IntegrationValues {
  const values = defaultActionValues(action);
  if (props.adapter.mode !== "demo") return values;
  const start = new Date();
  start.setUTCHours(0, 0, 0, 0);
  const end = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
  for (const field of action?.fields ?? []) {
    if (!field.required || field.type !== "text") continue;
    if (field.id === "startAt") values[field.id] = start.toISOString();
    else if (field.id === "endAt") values[field.id] = end.toISOString();
    else if (/(?:Id|Ref)$/.test(field.id))
      values[field.id] = props.connection.resourceIds[0] ?? "";
  }
  return values;
}

const resourceFields = new Set([
  "resourceId",
  "resource",
  "sourceId",
  "collectionId",
  "tableId",
  "indexId",
  "channelId",
  "repositoryId",
  "projectId",
  "databaseId",
  "siteId",
]);

/** Explicit values win. A resource binding is always a consumer-authorized ID. */
export function productActionValues(
  action: IntegrationAction | undefined,
  values: IntegrationValues,
  resourceId = "",
): IntegrationValues {
  const output = { ...defaultActionValues(action), ...values };
  if (resourceId) {
    output.resourceId = resourceId;
    for (const field of action?.fields ?? []) {
      if (resourceFields.has(field.id) && !output[field.id]) {
        output[field.id] = resourceId;
      }
    }
  }
  return output;
}

export function invalidProductField(
  action: Pick<IntegrationAction, "fields"> | undefined,
  values: IntegrationValues,
): IntegrationField | undefined {
  return action?.fields.find((field) => {
    const value = values[field.id];
    const empty =
      value === undefined ||
      (typeof value === "string" && !value.trim()) ||
      (Array.isArray(value) && value.length === 0);
    if (empty) return field.required === true;
    if (field.type === "number") {
      return !Number.isFinite(
        typeof value === "number" ? value : Number(value),
      );
    }
    if (field.type === "toggle") return typeof value !== "boolean";
    if (field.type === "select") {
      return !field.options?.some((option) => option.value === value);
    }
    return false;
  });
}

export function parseProductArguments(
  source: string,
): { ok: true; json: string } | { ok: false } {
  function valid(value: unknown, depth = 0): boolean {
    if (depth > 20) return false;
    if (
      value === null ||
      typeof value === "string" ||
      typeof value === "boolean"
    )
      return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (Array.isArray(value))
      return value.every((item) => valid(item, depth + 1));
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).every(
      ([key, item]) =>
        !["__proto__", "constructor", "prototype"].includes(key) &&
        valid(item, depth + 1),
    );
  }
  try {
    const value = JSON.parse(source);
    if (
      !value ||
      typeof value !== "object" ||
      Array.isArray(value) ||
      !valid(value)
    )
      return { ok: false };
    return { ok: true, json: JSON.stringify(value) };
  } catch {
    return { ok: false };
  }
}

/** The backend applies filters/sorting/page boundaries; the UI never re-pages results. */
export function productQueryValues(
  query: DataTableQuery,
  resourceId = "",
): IntegrationValues {
  const sort = query.sorting[0];
  const status = query.filters.find((filter) => filter.id === "status");
  const filterValue = status?.value;
  return {
    resourceId,
    query: query.search,
    search: query.search,
    filter: typeof filterValue === "string" ? filterValue : "",
    status: typeof filterValue === "string" ? filterValue : "",
    page: query.pagination.pageIndex,
    pageNumber: query.pagination.pageIndex + 1,
    pageIndex: query.pagination.pageIndex,
    pageSize: query.pagination.pageSize,
    limit: query.pagination.pageSize,
    offset: query.pagination.pageIndex * query.pagination.pageSize,
    sort: sort?.id ?? "",
    order: sort?.desc ? "desc" : "asc",
    direction: sort?.desc ? "desc" : "asc",
    filters: JSON.stringify(query.filters),
    sorting: JSON.stringify(query.sorting),
    queryState: JSON.stringify(query),
  };
}

export function mergeProductRecords(
  previous: readonly IntegrationRecord[],
  incoming: readonly IntegrationRecord[],
) {
  const records = new Map(previous.map((record) => [record.id, record]));
  for (const record of incoming) {
    if (!record.id) continue;
    const current = records.get(record.id);
    if (
      current &&
      Number.isFinite(Date.parse(current.updatedAt)) &&
      Number.isFinite(Date.parse(record.updatedAt)) &&
      Date.parse(record.updatedAt) < Date.parse(current.updatedAt)
    ) {
      continue;
    }
    records.set(record.id, record);
  }
  return [...records.values()];
}

export function optimisticProductRecord(
  record: IntegrationRecord,
  values: IntegrationValues,
  marker: string,
): IntegrationRecord {
  return {
    ...record,
    name: typeof values.name === "string" ? values.name : record.name,
    description:
      typeof values.description === "string"
        ? values.description
        : record.description,
    status: typeof values.status === "string" ? values.status : record.status,
    updatedAt: marker,
  };
}

/** Roll back only this mutation, never a newer query or another acknowledged write. */
export function rollbackProductRecord(
  records: readonly IntegrationRecord[],
  original: IntegrationRecord,
  marker: string,
) {
  return records.map((record) =>
    record.id === original.id && record.updatedAt === marker
      ? original
      : record,
  );
}

export function parseProductFields(
  source: string,
):
  | { ok: true; values: IntegrationValues }
  | { ok: false; reason: "json" | "values" } {
  let value: unknown;
  try {
    value = JSON.parse(source);
  } catch {
    return { ok: false, reason: "json" };
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, reason: "values" };
  }
  const entries = Object.entries(value);
  if (
    entries.some(
      ([key, item]) =>
        ["__proto__", "constructor", "prototype"].includes(key) ||
        !(
          typeof item === "string" ||
          typeof item === "boolean" ||
          (typeof item === "number" && Number.isFinite(item)) ||
          (Array.isArray(item) &&
            item.every((part) => typeof part === "string"))
        ),
    )
  ) {
    return { ok: false, reason: "values" };
  }
  return { ok: true, values: Object.fromEntries(entries) };
}

export function safeProductUrl(value?: string) {
  if (!value) return undefined;
  if (
    value.startsWith("/") &&
    !value.startsWith("//") &&
    !value.includes("\\")
  ) {
    return value;
  }
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) &&
      !url.username &&
      !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

export function productSearchSegments(text: string, query: string) {
  const term = query.trim();
  if (!term) return [{ text, match: false }];
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return text
    .split(new RegExp(`(${escaped})`, "ig"))
    .filter(Boolean)
    .map((part) => ({
      text: part,
      match: part.toLocaleLowerCase() === term.toLocaleLowerCase(),
    }));
}

export function productMapLocations(
  result: Extract<IntegrationResult, { kind: "map" }>,
) {
  const seen = new Set<string>();
  return result.locations.filter((location) => {
    if (
      !location.id ||
      seen.has(location.id) ||
      !Number.isFinite(location.latitude) ||
      !Number.isFinite(location.longitude) ||
      Math.abs(location.latitude) > 90 ||
      Math.abs(location.longitude) > 180
    ) {
      return false;
    }
    seen.add(location.id);
    return true;
  });
}

export type ProductFieldMapping = { source: string; target: string };
export function validProductMapping(mapping: readonly ProductFieldMapping[]) {
  const targets = new Set<string>();
  return (
    mapping.length > 0 &&
    mapping.every(({ source, target }) => {
      if (
        !source.trim() ||
        !target.trim() ||
        targets.has(target) ||
        ["__proto__", "constructor", "prototype"].includes(target)
      ) {
        return false;
      }
      targets.add(target);
      return true;
    })
  );
}

export function mapProductRecord(
  record: IntegrationRecord,
  mapping: readonly ProductFieldMapping[],
): IntegrationValues {
  const fields: IntegrationValues = {
    ...record.fields,
    id: record.id,
    name: record.name,
    title: record.name,
    status: record.status,
    description: record.description,
    type: record.type,
    updatedAt: record.updatedAt,
  };
  return Object.fromEntries(
    mapping
      .filter(
        ({ source, target }) =>
          source in fields &&
          !["__proto__", "constructor", "prototype"].includes(target),
      )
      .map(({ source, target }) => [target, fields[source]]),
  );
}

/** Only declarative primitive input fields are read; schema code is never evaluated. */
export function productToolFields(
  record?: IntegrationRecord,
): IntegrationField[] {
  const source = record?.fields?.inputSchema ?? record?.fields?.schema;
  if (typeof source !== "string" || source.length > 50_000) return [];
  try {
    const schema = JSON.parse(source);
    if (
      !schema ||
      typeof schema !== "object" ||
      !schema.properties ||
      typeof schema.properties !== "object"
    )
      return [];
    const required = new Set(
      Array.isArray(schema.required) ? schema.required : [],
    );
    return Object.entries(schema.properties)
      .filter(([id]) => !["__proto__", "constructor", "prototype"].includes(id))
      .flatMap(([id, value]) => {
        if (!value || typeof value !== "object") return [];
        const property = value as {
          title?: string;
          description?: string;
          type?: string;
          enum?: unknown[];
        };
        if (
          !["string", "number", "integer", "boolean"].includes(
            property.type ?? "",
          )
        )
          return [];
        const title = typeof property.title === "string" ? property.title : id;
        const options = Array.isArray(property.enum)
          ? property.enum
              .filter((item): item is string => typeof item === "string")
              .map((item) => ({ value: item, label: { en: item, es: item } }))
          : [];
        return [
          {
            id,
            label: { en: title, es: title },
            description:
              typeof property.description === "string"
                ? { en: property.description, es: property.description }
                : undefined,
            type: options.length
              ? "select"
              : property.type === "boolean"
                ? "toggle"
                : ["number", "integer"].includes(property.type ?? "")
                  ? "number"
                  : "text",
            options: options.length ? options : undefined,
            required: required.has(id),
          } satisfies IntegrationField,
        ];
      });
  } catch {
    return [];
  }
}

"use client";

import { useEffect, useId, useState, type ReactNode } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { AlertCircle, Check, ExternalLink, RefreshCw, X } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Progress } from "@/components/ui/progress";
