export function ProductEmpty({ children }: { children: ReactNode }) {
  return (
    <p className="rounded-xl border border-dashed border-border bg-surface-subtle/50 p-6 text-center text-xs leading-6 text-muted-foreground">
      {children}
    </p>
  );
}

