const selectedFiles = z
  .array(
    z.object({
      id: z
        .string()
        .min(1)
        .max(200)
        .refine((value) => !/[\u0000-\u001f]/.test(value)),
      name: z.string().min(1).max(300),
      mimeType: z.string().min(1).max(200),
    }),
